"""Write the parameter catalogs of the Rust TensorRT-LLM, llama.cpp and Ollama adapters from the Python ones.

The Python catalogs (`backend/src/engine_console/adapters/{trtllm,llamacpp,ollama}_params.py` of the last Python
release, gen/pyref.py) are data: one
`a(_p(...))` call per parameter. This script reads those calls with `ast` and writes the same calls in Rust, keyword
for keyword, between the markers of `backend/crates/ec-hub/src/adapters/<engine>_params.rs`:

    // ---- generated by backend/parity/gen/catalog_ws_a2.py: begin ----
    ...
    // ---- generated by backend/parity/gen/catalog_ws_a2.py: end ----

so every label, help text, default and choice list is copied, never retyped. Names of module constants (DOC_KV,
KV_CACHE_DTYPES, ...) stay names (the Rust file defines the same constants); any other expression is evaluated in the
Python module and written as a literal. The Rust `p()` builder of each file mirrors that engine's `_p()` helper; the
golden test (tests/test_ws_a2_goldens.rs) proves the result equals `param_catalog()` value for value.

    python3 backend/parity/gen/catalog_ws_a2.py && (cd backend && cargo fmt -p ec-hub)

Standard library only (no engine_console import is needed to read the calls; constants are evaluated from the source).
"""
from __future__ import annotations

import ast
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
from pyref import WORKSPACE, tree  # noqa: E402

REPO = WORKSPACE.parent
PY = tree() / "backend" / "src" / "engine_console" / "adapters"
RS = WORKSPACE / "crates" / "ec-hub" / "src" / "adapters"
BEGIN = "// ---- generated by backend/parity/gen/catalog_ws_a2.py: begin ----"
END = "// ---- generated by backend/parity/gen/catalog_ws_a2.py: end ----"


def rs_str(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            out.append(f"\\u{{{ord(ch):x}}}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def rs_value(v: Any) -> str:
    """A serde_json::Value literal for a ParamSpec default (int stays int, float stays float)."""
    if v is None:
        return "Value::Null"
    if isinstance(v, bool):
        return f"Value::Bool({str(v).lower()})"
    if isinstance(v, int):
        return f"Value::from({v}_i64)"
    if isinstance(v, float):
        return f"Value::from({float_lit(v)})"
    if isinstance(v, str):
        return f"Value::from({rs_str(v)})"
    raise TypeError(type(v).__name__)


def float_lit(v: float) -> str:
    """A Rust f64 literal with the same value (Python's repr is a valid Rust literal for finite floats)."""
    return repr(float(v))


def module_env(path: Path) -> dict[str, Any]:
    """Module-level constants of a params file, evaluated without importing the package."""
    tree = ast.parse(path.read_text(encoding="utf-8"))
    env: dict[str, Any] = {}
    for node in tree.body:
        targets = []
        if isinstance(node, ast.Assign):
            targets = [t.id for t in node.targets if isinstance(t, ast.Name)]
            value = node.value
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.value is not None:
            targets = [node.target.id]
            value = node.value
        else:
            continue
        try:
            val = eval(compile(ast.Expression(value), str(path), "eval"), {"frozenset": frozenset}, dict(env))  # noqa: S307
        except Exception:  # noqa: BLE001 - not a plain constant
            continue
        for t in targets:
            env[t] = val
    return env


def calls(path: Path) -> list[ast.Call]:
    tree = ast.parse(path.read_text(encoding="utf-8"))
    fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "build_catalog")
    out = []
    for node in ast.walk(fn):
        if isinstance(node, ast.Call) and getattr(node.func, "id", None) == "_p":
            out.append(node)
    out.sort(key=lambda n: (n.lineno, n.col_offset))
    return out


def arg(node: ast.AST, env: dict[str, Any], consts: set[str], kind: str) -> str:
    """Rust text for one argument: a constant name when the Python passes one, else a literal."""
    if isinstance(node, ast.Name) and node.id in consts:
        return node.id
    val = eval(compile(ast.Expression(node), "<arg>", "eval"), {}, dict(env))  # noqa: S307
    if kind == "str":
        return rs_str(val)
    if kind == "num":
        return float_lit(val)
    if kind == "choices":
        return "&[" + ", ".join(rs_str(x) for x in val) + "]"
    if kind == "value":
        return rs_value(val)
    raise ValueError(kind)


KW_KIND = {"default": "value", "choices": "choices", "min": "num", "max": "num", "docs": "str", "unit": "str",
           "lvl": "str"}
BOOL_KW = ("adv", "mem", "expert")


def render(engine: str, consts: set[str]) -> str:
    path = PY / f"{engine}_params.py"
    env = module_env(path)
    lines = ["pub fn build_catalog() -> Vec<ParamSpec> {", "    vec!["]
    for call in calls(path):
        pos = [arg(a, env, consts, "str") for a in call.args]
        chain = []
        for kw in call.keywords:
            if kw.arg in BOOL_KW:
                val = eval(compile(ast.Expression(kw.value), "<kw>", "eval"), {}, dict(env))  # noqa: S307
                if val:
                    chain.append(f".{kw.arg}()")
                continue
            kind = KW_KIND[kw.arg]
            if kind == "value":
                val = eval(compile(ast.Expression(kw.value), "<kw>", "eval"), {}, dict(env))  # noqa: S307
                if isinstance(kw.value, ast.Name) and kw.value.id in consts and isinstance(val, str):
                    chain.append(f".default(Value::from({kw.value.id}))")
                else:
                    chain.append(f".default({rs_value(val)})")
            else:
                chain.append(f".{kw.arg}({arg(kw.value, env, consts, kind)})")
        lines.append(f"        p({', '.join(pos)}){''.join(chain)}.build(),")
    lines += ["    ]", "}"]
    return "\n".join(lines)


CONSTS = {
    "trtllm": {"DOC_SERVE", "DOC_YAML", "DOC_METRICS", "DOC_KV", "DOC_PARALLEL", "DOC_QUANT", "DOC_SPEC", "DOC_ATTENTION",
               "DOC_OVERLAP", "DOC_COMPILE", "DOC_GUIDED", "DOC_SAMPLING", "DOC_MULTIMODAL", "SRC_LLM_ARGS",
               "LOG_LEVELS", "REASONING_PARSERS", "TOOL_PARSERS", "KV_CACHE_DTYPES", "MAMBA_CACHE_DTYPES",
               "MOE_BACKENDS", "ATTENTION_BACKENDS", "ALLREDUCE_STRATEGIES", "SAMPLER_TYPES", "CAPACITY_POLICIES",
               "CHUNKING_POLICIES", "GUIDED_BACKENDS", "NVFP4_GEMM_BACKENDS", "ORCHESTRATORS", "TOKENIZER_MODES",
               "CUSTOM_TOKENIZERS", "SPEC_TYPES", "YAML_EXTRA_FLAG", "DEFAULT_IMAGE"},
    "llamacpp": {"CACHE_TYPES", "SPEC_TYPES", "LOAD_MODES"},
    "ollama": {"KV_CACHE_TYPES", "CONTEXT_DOCS", "DOCS"},
}


def main() -> int:
    for engine, consts in CONSTS.items():
        target = RS / f"{engine}_params.rs"
        text = target.read_text(encoding="utf-8")
        if BEGIN not in text or END not in text:
            print(f"{target}: markers missing", file=sys.stderr)
            return 2
        head, rest = text.split(BEGIN, 1)
        _, tail = rest.split(END, 1)
        body = render(engine, consts)
        target.write_text(f"{head}{BEGIN}\n{body}\n{END}{tail}", encoding="utf-8")
        print(f"{target.relative_to(REPO)}: {body.count('.build()')} parameters", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
